std::string rle_encode(const std::string& s) {
    if (s.empty()) return "";
    std::vector<std::pair<int, char>> pairs;
    int count = 1;
    for (size_t i = 1; i < s.size(); ++i) {
        if (s[i] == s[i - 1]) {
            ++count;
        } else {
            pairs.push_back({count, s[i - 1]});
            count = 1;
        }
    }
    pairs.push_back({count, s.back()});
    std::string result;
    for (const auto& p : pairs) {
        result += std::to_string(p.first) + p.second;
    }
    return result;
}

