#include <stack>
#include <string>

bool balanced(const std::string& s) {
    std::stack<char> stack;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            stack.push(c);
        } else if (c == ')' && !stack.empty() && stack.top() == '(') {
            stack.pop();
        } else if (c == ']' && !stack.empty() && stack.top() == '[') {
            stack.pop();
        } else if (c == '}' && !stack.empty() && stack.top() == '{') {
            stack.pop();
        } else {
            return false;
        }
    }
    return stack.empty();
}

#include <vector>

std::vector<int> count_bits(int n) {
    std::vector<int> bits(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        bits[i] = bits[i >> 1] + (i & 1);
    }
    return bits;
}

module mux4 (
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    input [1:0] sel,
    output reg [7:0] y
);

    always @(*) begin
        case (sel)
            2'b00: y = a;
            2'b01: y = b;
            2'b10: y = c;
            2'b11: y = d;
            default: y = 8'b00000000;
        endcase
    end

endmodule

module parity8 (
    input [7:0] d,
    output reg even,
    output reg odd
);

    always @(*) begin
        even = d ^ (d >> 1) ^ (d >> 2) ^ (d >> 3) ^ (d >> 4) ^ (d >> 5) ^ (d >> 6) ^ (d >> 7);
        odd = ~even;
    end

endmodule

module rise_detect (
    input clk,
    input rst,
    input sig,
    output reg pulse
);

    reg [1:0] sig_prev;
    reg [1:0] sig_now;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sig_prev <= 2'b00;
            sig_now <= 2'b00;
            pulse <= 1'b0;
        end else begin
            sig_prev <= sig_now;
            sig_now <= sig;
            pulse <= sig_now & ~sig_prev;
        end
    end

endmodule
